import React, { useState } from "react";
import axios from "axios";
import { Mail, Send } from "lucide-react";

export default function UserSignin() {

  const [email,setEmail] = useState("")
  const [loading,setLoading] = useState(false)
  const [message,setMessage] = useState("")

  const createAuth = async (e) => {

    e.preventDefault()

    setLoading(true)
    setMessage("")

    try{

      const res = await axios.post(
        "http://localhost:3597/api/user/login",
        {email},
        {timeout:10000} // 10 second max wait
      )

      localStorage.setItem("authToken",res.data.token)

      setMessage("Magic link sent to your email ✉️")

    }catch(err){

      setMessage(
        err.response?.data?.message ||
        "Something went wrong"
      )

    }finally{
      setLoading(false)
    }
  }

  return (

    <div className="min-h-screen flex items-center justify-center px-6">

      <div className="glass p-10 rounded-2xl w-[420px] fade-up">

        <div className="flex items-center gap-3 mb-6 justify-center">

          <Mail className="text-cyan-400"/>
          <h1 className="text-3xl font-bold">
            Magic Link Login
          </h1>

        </div>

        <p className="text-sm text-gray-300 text-center mb-6">
          Enter your email to receive a secure login link.
        </p>

        <form
        onSubmit={createAuth}
        className="flex flex-col gap-4">

          <input
          type="email"
          placeholder="Enter your email"
          className="p-3 rounded-lg bg-black/30 border border-white/10 outline-none focus:border-cyan-400"
          value={email}
          onChange={(e)=>setEmail(e.target.value)}
          required
          />

          <button
          className="btn-glow p-3 rounded-lg flex items-center justify-center gap-2 font-semibold"
          disabled={loading}
          >

          {loading ? "Sending..." : "Send Magic Link"}

          <Send size={18}/>

          </button>

        </form>

        {message && (

          <p className="text-center mt-4 text-sm text-cyan-300">
            {message}
          </p>

        )}

      </div>

    </div>

  )
}
